// Generated by Claude Code
package ui;

import grading.assessment.AssessmentDefinition;
import grading.common.Messages;
import grading.submission.FindingSeverity;
import grading.submission.SubmissionFinding;
import grading.tester.TesterValidationResult;
import java.util.List;

/** The text shown after importing testers or submissions: the one-line summaries and the failure reports. */
final class ImportResults {

    private ImportResults() {
    }

    /** Such as "5 of 5 tester files valid". */
    static String testerSummary(TesterValidationResult result) {
        return result.testerFiles().size() + " of " + AssessmentDefinition.testerFiles().size()
                + " tester files valid";
    }

    /** Such as "6 submissions · 5 ready · 1 need attention". */
    static String submissionSummary(int total, long ready, long needingAttention) {
        return total + (total == 1 ? " submission" : " submissions") + " · " + ready + " ready"
                + (needingAttention == 0 ? "" : " · " + needingAttention + " need attention");
    }

    /** Added when a tester import fails or is invalid but the earlier, valid testers are still used. */
    static String keptTestersNote(boolean earlierTestersValid) {
        return earlierTestersValid
                ? "\nThe tester files imported earlier are still valid and are used for grading.\n" : "";
    }

    /** Why a tester folder was not accepted, said in the tester panel. */
    static String testerRejection(TesterValidationResult result, boolean earlierTestersValid) {
        return testerProblem(result)
                + (earlierTestersValid ? " The tester files imported earlier are still used." : "");
    }

    private static String testerProblem(TesterValidationResult result) {
        if (result.testerFiles().isEmpty()) {
            return "This is not a tester folder: it has none of the tester files ("
                    + String.join(", ", AssessmentDefinition.testerFiles()) + ").";
        }
        List<SubmissionFinding> errors = result.findings().stream()
                .filter(finding -> finding.severity() == FindingSeverity.ERROR).toList();
        return "These tester files were not accepted: " + errors.getFirst().message()
                + (errors.size() > 1 ? " (" + (errors.size() - 1) + " more in the Activity log)" : "");
    }

    /** A tester folder that could not be read at all, said in the tester panel. */
    static String testerReadFailure(Throwable failure, boolean earlierTestersValid) {
        return "This folder could not be read: " + Messages.describe(failure)
                + (earlierTestersValid ? " The tester files imported earlier are still used." : "");
    }

    /** Why a submissions folder was not accepted, said in the submissions panel. */
    static String submissionRejection(Throwable failure, boolean earlierSubmissionsKept) {
        return Messages.describe(failure)
                + (earlierSubmissionsKept ? " The submissions imported earlier are still used." : "");
    }

    static String testerFailure(Throwable failure, boolean earlierTestersValid) {
        return "Tester-file validation failed\n"
                + Messages.describe(failure)
                + "\n  Next step for marker: Confirm that the selected folder is readable and contains "
                + "the official tester sources, then import it again.\n"
                + keptTestersNote(earlierTestersValid);
    }

    static String submissionFailure(Throwable failure, boolean earlierSubmissionsKept) {
        return "Submission validation failed\n"
                + Messages.describe(failure)
                + "\n  Next step for marker: Confirm that the selected folder is readable, repair or "
                + "re-extract it if necessary, then import it again.\n\n"
                + "No source files were changed."
                + (earlierSubmissionsKept ? " The previously imported submissions are kept." : "")
                + "\n";
    }
}
